css:
.afl-root[data-afl-scope="s3ef30fbd"]{margin-left:21px;color:windowtext;background-color:window;layout-grid:none}
.afl-root[data-afl-scope="s3ef30fbd"] .xdListItem{display:inline-block;width:100%;vertical-align:text-top}
.afl-root[data-afl-scope="s3ef30fbd"] .xdListBox,.afl-root[data-afl-scope="s3ef30fbd"] .xdComboBox{margin:1px}
.afl-root[data-afl-scope="s3ef30fbd"] .xdInlinePicture{margin:1px}
.afl-root[data-afl-scope="s3ef30fbd"] .xdSection{border:1pt solid #FFFFFF;margin:6px 0px 6px 0px;padding:1px 1px 1px 5px}
.afl-root[data-afl-scope="s3ef30fbd"] .xdRepeatingSection{border:1pt solid #FFFFFF;margin:6px 0px 6px 0px;padding:1px 1px 1px 5px}
.afl-root[data-afl-scope="s3ef30fbd"] .xdRepeatingTable{BORDER-TOP-STYLE:none;BORDER-RIGHT-STYLE:none;BORDER-LEFT-STYLE:none;BORDER-BOTTOM-STYLE:none;BORDER-COLLAPSE:collapse;WORD-WRAP:break-word}
.afl-root[data-afl-scope="s3ef30fbd"] .xdFileAttachment{display:inline-block;margin:1px}
.afl-root[data-afl-scope="s3ef30fbd"] .xdTextBox{display:inline-block;white-space:nowrap;text-overflow:ellipsis;padding:1px;margin:1px;border:1pt solid #dcdcdc;color:windowtext;background-color:window;overflow:hidden;text-align:left}
.afl-root[data-afl-scope="s3ef30fbd"] .xdRichTextBox{display:inline-block;padding:1px;margin:1px;border:1pt solid #dcdcdc;color:windowtext;background-color:window;overflow-x:hidden;word-wrap:break-word;text-overflow:ellipsis;text-align:left;font-weight:normal;font-style:normal;text-decoration:none;vertical-align:baseline}
.afl-root[data-afl-scope="s3ef30fbd"] .xdDTPicker{display:inline;margin:1px;margin-bottom:2px;border:1pt solid #dcdcdc;color:windowtext;background-color:window;overflow:hidden;text-indent:0}
.afl-root[data-afl-scope="s3ef30fbd"] .xdDTText{height:100%;width:100%;margin-right:22px;overflow:hidden;padding:0px;white-space:nowrap}
.afl-root[data-afl-scope="s3ef30fbd"] .xdDTButton{margin-left:-21px;height:18px;width:20px}
.afl-root[data-afl-scope="s3ef30fbd"] .xdRepeatingTable TD{VERTICAL-ALIGN:top}
.afl-root[data-afl-scope="s3ef30fbd"]{FONT-FAMILY:Calibri, sans-serif;FONT-SIZE:10pt}
.afl-root[data-afl-scope="s3ef30fbd"] TABLE{FONT-SIZE:10pt}
.afl-root[data-afl-scope="s3ef30fbd"] h1{FONT-SIZE:16pt;COLOR:#17365d}
.afl-root[data-afl-scope="s3ef30fbd"] h2{FONT-SIZE:12pt;COLOR:#365f91}
.afl-root[data-afl-scope="s3ef30fbd"] TABLE.xdLayout TD{BORDER-TOP:medium none;BORDER-RIGHT:medium none;BORDER-BOTTOM:medium none;BORDER-LEFT:medium none}
.afl-root[data-afl-scope="s3ef30fbd"] TABLE.msoUcTable TD{BORDER-TOP:1pt solid;BORDER-RIGHT:1pt solid;BORDER-BOTTOM:1pt solid;BORDER-LEFT:1pt solid}
.afl-root[data-afl-scope="s3ef30fbd"]{FONT-SIZE:10pt;FONT-FAMILY:Calibri}
.afl-root[data-afl-scope="s3ef30fbd"] SELECT{FONT-SIZE:10pt;FONT-FAMILY:Calibri}
.afl-root[data-afl-scope="s3ef30fbd"] TABLE{FONT-SIZE:10pt;FONT-FAMILY:Calibri;TEXT-TRANSFORM:none;FONT-WEIGHT:normal;COLOR:black;FONT-STYLE:normal}
.afl-root[data-afl-scope="s3ef30fbd"] .optionalPlaceholder{FONT-SIZE:9pt;TEXT-DECORATION:none;FONT-FAMILY:Calibri;FONT-WEIGHT:normal;COLOR:#333333;FONT-STYLE:normal}
.afl-root[data-afl-scope="s3ef30fbd"] .langFont{FONT-SIZE:10pt;FONT-FAMILY:Calibri;WIDTH:150px}
.afl-root{contain:layout paint;position:relative}
:where(.afl-root .afl-required){position:relative}
.afl-root .afl-required::after,.afl-root .afl-required-mark{content:"*";position:absolute;right:3px;top:50%;width:8px;height:8px;margin-top:-4px;color:#FF0000;font:bold 12px/12px Arial,sans-serif;text-align:center;overflow:visible;pointer-events:none}
.afl-root .afl-required-mark{position:relative;display:inline-block;right:auto;top:auto;margin:0 0 0 -11px;vertical-align:middle}
:where(.afl-root [data-afl-ctrl]){min-height:1lh}
:where(.afl-root span[data-afl-ctrl]){display:inline-block}
:where(.afl-root,.afl-root *){box-sizing:border-box}
:where(.afl-root table[style*="table-layout:fixed" i]>:is(thead,tbody,tfoot)>tr>:is(td,th)){overflow:hidden}
.afl-root[data-afl-scope] .xdTextBox{overflow:clip}
:where(.afl-root span[data-afl-ctrl]:empty)::before{content:"\200b"}
:where(.afl-root){margin:15px 10px}
:where(.afl-root :is(h1,h2,h3,h4,h5,h6)){margin-top:14pt;margin-bottom:14pt}
:where(:is(.afl-root,.afl-root :is(td,th,[data-afl-ctrl]))>:is(h1,h2,h3,h4,h5,h6,p):first-child,:is(.afl-root,.afl-root :is(td,th,[data-afl-ctrl]))>div:first-child>:is(h1,h2,h3,h4,h5,h6,p):first-child,:is(.afl-root,.afl-root :is(td,th,[data-afl-ctrl]))>div:first-child>div:first-child>:is(h1,h2,h3,h4,h5,h6,p):first-child){margin-top:0}
:where(.afl-root select:not([multiple]):is(:not([size]),[size="0"],[size="1"])){min-height:calc(1lh + 6px)}
:where(.afl-root .xdInlinePicture>img){vertical-align:top}
.afl-root .afl-icon{display:inline-block;box-sizing:border-box;width:16px;height:16px;vertical-align:middle;flex:none}
.afl-root .afl-icon-calendar{border:1px solid #626f86;border-top-width:4px;border-radius:2px;background:#fff linear-gradient(#626f86,#626f86) 3px 3px/2px 2px repeat-x;background-clip:padding-box}
.afl-root .afl-icon-picture{width:48px;height:36px;border:1px dashed #8590a2;background:linear-gradient(135deg,transparent 55%,#c1c7d0 55%,#c1c7d0 70%,transparent 70%)}
.afl-root .afl-icon-signature{width:20px;border-bottom:2px solid #44546f;background:linear-gradient(150deg,transparent 45%,#44546f 45%,#44546f 55%,transparent 55%)}
.afl-root .afl-icon-unknown{border:1px dotted #8590a2}
.afl-root .afl-icon-file{width:22px;height:28px;border:1px solid #8590a2;border-radius:0 6px 0 0;background:#fff repeating-linear-gradient(#fff 0 2px,#c1c7d0 2px 3px) 3px 6px/14px 18px no-repeat;vertical-align:top}
.afl-root .afl-attachment{display:inline-flex;align-items:center;vertical-align:top}
.afl-root .afl-attachment-filled{box-sizing:border-box;min-width:100%;min-height:59px;padding:5px 8px 10px 11px;gap:10px;border:1px solid #dcdcdc;white-space:nowrap}
.afl-root .afl-attachment-text{display:flex;flex-direction:column;align-self:flex-start;line-height:14px}
.afl-root .afl-unsupported{box-sizing:border-box;min-height:24px;padding:4px 6px;border:1px solid #8590a2;background:#dcdfe4;color:#44546f;font:12px/16px sans-serif}
:where(.afl-root [nowrap]){white-space:nowrap}
.afl-root[data-afl-scope] div.xdDTPicker{display:inline-flex;align-items:center;box-sizing:border-box;max-width:calc(100% - 2px);vertical-align:middle}
.afl-root[data-afl-scope] .xdDTPicker .xdDTText{flex:1 1 auto;min-width:0;width:auto;margin-right:0}
.afl-root[data-afl-scope] .xdDTPicker .xdDTButton{flex:none;display:inline-flex;align-items:center;justify-content:center;margin:0;padding:0;border:0;background:none}
